import request from "@/router/axios";

export default {
  data() {
    return {
      visible: false,
      dataForm: {
        id: 0,
        beanName: '',
        params: '',
        cronExpression: '',
        remark: '',
        status: 0,
        type: '',
      },
      dataRule: {
        beanName: [
          {required: true, message: '用户名不能为空', trigger: 'blur'}
        ],
        cronExpression: [
          {required: true, message: 'cron表达式不能为空', trigger: 'blur'}
        ]
      }
    }
  },
  methods: {
    init(id) {
      this.dataForm.id = id || 0
      this.visible = true
      this.$nextTick(() => {
        this.$refs['dataForm'].resetFields()
        if (this.dataForm.id) {
          request({
            url: `/api/idevelop-data/sys/schedule/info/${this.dataForm.id}`,
            method: 'get',
            params: {}
          }).then(({data}) => {
            if (data) {
              this.dataForm.beanName = data.beanName
              this.dataForm.params = data.params
              this.dataForm.cronExpression = data.cronExpression
              this.dataForm.remark = data.remark
              this.dataForm.status = data.status
              this.dataForm.type = data.type
            }
          })
        }
      })
    },
    // 表单提交
    dataFormSubmit() {
      this.$refs['dataForm'].validate((valid) => {
        if (valid) {
          let url = '/api/idevelop-data/sys/schedule/save'
          if (this.dataForm.id) {
            url = '/api/idevelop-data/sys/schedule/update'
          }
          request({
            url: url,
            method: 'post',
            data: {
              'jobId': this.dataForm.id || undefined,
              'beanName': this.dataForm.beanName,
              'params': this.dataForm.params,
              'cronExpression': this.dataForm.cronExpression,
              'remark': this.dataForm.remark,
              'status': !this.dataForm.id ? undefined : this.dataForm.status,
              'type': this.dataForm.type,
            }
          }).then(({data}) => {
            if (data) {
              this.$message({
                message: '操作成功',
                type: 'success',
                duration: 1500,
              })
              this.visible = false;
              this.$emit('refreshDataList')
              this.$emit('close')
            } else {
              this.$message.error(data.msg)
            }
          })
        }
      })
    }
  }
}
